# ENGR 243 (Dynamics, Dr. Gomaa, Fall 2026) — theory/concept bank aligned to Lectures 1–22 (Beer & Johnston Ch 11–17).
# Tags follow STYLE.md against the one-page "Formulae Sheet (Updated)". The final also allows one handwritten double-sided crib sheet:
# results that are NOT on the formulae sheet carry a "crib sheet" note so they can go on it.
C = "engr243"
SH, DEF = "(sheet)", "(definition, not on the sheet)"
CRIB = "Not on the formulae sheet, so it's worth a line on your crib sheet."
L = lambda n, t: f"Lecture {n} – {t}"
Q = []
def add(kind, id, topic, q, exp, src, **kw):
    d = dict(id=f"e243-{id}", course=C, topic=topic, type=kind, question=q, explanation=exp, source=src); d.update(kw); Q.append(d)
def mcq(id, topic, q, choices, ans, exp, src): add("mcq", id, topic, q, exp, src, choices=choices, answer=ans)
def tf(id, topic, q, ans, exp, src): add("tf", id, topic, q, exp, src, answer=ans)
def sa(id, topic, q, ans, exp, src, kw=()): add("short", id, topic, q, exp, src, answer=ans, keywords=list(kw))

T = "Particle kinematics (Ch 11)"
mcq("pk-01", T, "If acceleration is given as a function of position, $a(x)$, which relation links $v$ and $x$?", ["$v\\,dv=a\\,dx$", "$dv=a\\,dt$", "$dx=v\\,dt$", "$a=dv/dx$"], 0, "(derived) $a=\\dfrac{dv}{dt}=\\dfrac{dv}{dx}\\dfrac{dx}{dt}$ (chain rule)\n$=v\\dfrac{dv}{dx}$\n" + CRIB, L(1, "Rectilinear Motion"))
mcq("pk-02", T, "For uniformly accelerated rectilinear motion, which is correct?", ["$v^2=v_0^2+2a(x-x_0)$", "$v=v_0+ax$", "$x=x_0+v_0t+at^2$", "$v^2=v_0^2+at$"], 0, "Constant-$a$ rows " + SH + ":\n$v=v_0+a(t-t_0)$\n$x=x_0+v_0(t-t_0)+\\tfrac a2(t-t_0)^2$\nThese are valid ONLY when $a$ is constant.", L(2, "Uniformly Accelerated Motion"))
tf("pk-03", T, "The area under a $v$–$t$ curve between $t_1$ and $t_2$ equals $x_2-x_1$.", True, "$dx=v\\,dt$ " + DEF + ", so integrating gives the area.\nThe area under $a$–$t$ is $\\Delta v$; the slope of $v$–$t$ is $a$.", L(1, "Rectilinear Motion"))
tf("pk-04", T, "Total distance travelled equals displacement only if the particle never reverses.", True, "Find where $v=0$, then add the distance of each leg as a positive number.", L(1, "Rectilinear Motion"))
mcq("pk-05", T, "Relative motion: $\\vec v_B=$", ["$\\vec v_A+\\vec v_{B/A}$", "$\\vec v_A-\\vec v_{B/A}$", "$\\vec v_{B/A}-\\vec v_A$", "$\\vec v_A\\vec v_{B/A}$"], 0, "$\\vec v_B=\\vec v_A+\\vec v_{B/A}$ " + SH + "\nValid for a translating (non-rotating) frame. $\\vec v_{B/A}$ = velocity of B as seen by an observer moving with A.", L(3, "Relative & Dependent Motion"))
sa("pk-06", T, "How do you set up a dependent-motion (cable) problem?", "Write the total cable length with position coordinates from fixed datums: $x_A+2x_B+\\dots=$ const. Differentiate once for velocities, twice for accelerations.", "One equation per cable. Constant lengths around pulleys drop out when you differentiate.\nSigns: a positive $v$ means the coordinate grows (moving away from the datum).\n" + CRIB, L(3, "Dependent Motion (Cables)"), ["length constant", "fixed datum", "differentiate"])
mcq("pk-07", T, "In projectile motion with no drag, which is TRUE?", ["The horizontal velocity is constant; the vertical acceleration is $-9.81\\ \\mathrm{m/s^2}$", "Both components are constant", "The horizontal acceleration is $g$", "The speed is constant"], 0, "Projectile rows " + SH + ":\n$x=x_0+v_{x0}(t-t_0)$\n$v_y=v_{y0}-9.81(t-t_0)$\n$y=y_0+v_{y0}(t-t_0)-4.905(t-t_0)^2$\nThe sheet uses $y$ positive up, so $g$ appears with a minus sign.", L(5, "Projectile Motion"))
mcq("pk-08", T, "In normal–tangential coordinates, the acceleration is:", ["$\\vec a=a_t\\vec e_t+\\dfrac{v^2}{\\rho}\\vec e_n$", "$\\vec a=\\dfrac{v^2}{\\rho}\\vec e_t+a_t\\vec e_n$", "$\\vec a=\\rho\\dot\\theta\\,\\vec e_t$", "$\\vec a=\\dot v\\,\\vec e_n$"], 0, "n–t row " + SH + "\n$a_t=\\dot v$ (changes the speed)\n$a_n=v^2/\\rho$ always points toward the centre of curvature (changes the direction)", L(5, "n-t Coordinates"))
tf("pk-09", T, "A car at constant speed around a curve has zero acceleration.", False, "$a_t=0$, but $a_n=v^2/\\rho\\ne0$ " + SH + " because the direction keeps changing.", L(6, "n-t Components"))
mcq("pk-10", T, "In polar coordinates, the radial acceleration is:", ["$a_r=\\ddot r-r\\dot\\theta^2$", "$a_r=\\ddot r$", "$a_r=r\\ddot\\theta+2\\dot r\\dot\\theta$", "$a_r=\\ddot r+r\\dot\\theta^2$"], 0, "r–θ row " + SH + ":\n$\\vec a=[\\ddot r-r\\dot\\theta^2]\\vec e_r+[2\\dot r\\dot\\theta+r\\ddot\\theta]\\vec e_\\theta$\nThe $-r\\dot\\theta^2$ term points inward (centripetal).", L(6, "r-θ Components"))
mcq("pk-11", T, "In polar coordinates, the velocity is:", ["$\\vec v=\\dot r\\,\\vec e_r+r\\dot\\theta\\,\\vec e_\\theta$", "$\\vec v=r\\dot\\theta\\,\\vec e_r+\\dot r\\,\\vec e_\\theta$", "$\\vec v=\\dot r\\,\\vec e_r+\\dot\\theta\\,\\vec e_\\theta$", "$\\vec v=r\\,\\vec e_r$"], 0, "r–θ row " + SH + "\nThe radial part comes from $r$ changing length; the transverse part comes from $r$ rotating.", L(6, "r-θ Components"))

T = "Rigid-body kinematics (Ch 15)"
sa("rk-01", T, "Name the types of plane rigid-body motion.", "Translation (rectilinear or curvilinear), rotation about a fixed axis, and general plane motion (translation + rotation).", "In translation every point has the same $\\vec v$ and $\\vec a$, and $\\omega=0$.", L(7, "Translation & Fixed-Axis Rotation"), ["translation", "fixed-axis rotation", "general plane motion"])
tf("rk-02", T, "In curvilinear translation all points follow identical parallel curves and the body doesn't rotate.", True, "Example: a Ferris-wheel gondola that stays upright.", L(7, "Translation"))
mcq("rk-03", T, "For a point at distance $r$ from a fixed rotation axis:", ["$v=r\\omega$, $a_t=r\\alpha$, $a_n=r\\omega^2$", "$v=r\\alpha$, $a_t=r\\omega$, $a_n=r\\omega$", "$v=\\omega/r$, $a_t=\\alpha/r$", "$v=r\\omega^2$, $a_n=r\\omega$"], 0, "Vector rows " + SH + ":\n$\\vec v=\\vec\\omega\\times\\vec r$\n$\\vec a=\\vec\\alpha\\times\\vec r+\\vec\\omega\\times(\\vec\\omega\\times\\vec r)$\nThe second term has magnitude $r\\omega^2$ and points toward the axis.", L(7, "Fixed-Axis Rotation"))
mcq("rk-04", T, "Two meshing gears (radii $r_A$, $r_B$) satisfy:", ["$r_A\\omega_A=r_B\\omega_B$", "$\\omega_A=\\omega_B$", "$r_B\\omega_A=r_A\\omega_B$", "$\\omega_A+\\omega_B=0$, equal magnitudes"], 0, "(derived) The contact points have equal speed: $v=r\\omega$ on each gear.\nExternal gears turn in opposite directions. A belt with no slip gives the same speed relation.", L(8, "Fixed-Axis Rotation Examples"))
mcq("rk-05", T, "For general plane motion, the relative-velocity equation is:", ["$\\vec v_B=\\vec v_A+\\omega\\vec k\\times\\vec r_{B/A}$", "$\\vec v_B=\\vec v_A+\\alpha\\vec k\\times\\vec r_{B/A}$", "$\\vec v_B=\\vec v_A-\\omega^2\\vec r_{B/A}$", "$\\vec v_B=\\vec\\omega\\times\\vec v_A$"], 0, "Row " + SH + "\nB moves on a circle around A, so $\\vec v_{B/A}$ is perpendicular to $\\vec r_{B/A}$.", L(8, "General Plane Motion"))
mcq("rk-06", T, "The instantaneous centre of zero velocity (IC) is located:", ["Where the lines perpendicular to the velocities of two points intersect", "At the centre of mass", "Where the acceleration is zero", "Midway between two points"], 0, "(derived) Each velocity is perpendicular to the line from the IC, since $\\vec v=\\vec\\omega\\times\\vec r_{/IC}$ " + SH + ".\nThen $v_P=\\omega\\,r_{P/IC}$.\n" + CRIB, L(9, "IC Method"))
tf("rk-07", T, "The IC has zero velocity AND zero acceleration at that instant.", False, "In general its acceleration is NOT zero, so the IC can't be used for accelerations. Use the relative-acceleration row " + SH + " instead.", L(9, "IC Method"))
mcq("rk-08", T, "For a wheel of radius $r$ rolling without slipping, the centre O satisfies:", ["$v_O=r\\omega$, $a_O=r\\alpha$", "$v_O=0$", "$v_O=2r\\omega$", "$a_O=r\\omega^2$"], 0, "(derived) The contact point is the IC, so $v_O=\\omega r$.\nDifferentiate: $a_O=r\\alpha$.\nThe contact point's acceleration is $r\\omega^2$, pointing up toward O.\n" + CRIB, L(9, "General Plane Motion"))
mcq("rk-09", T, "The top of a wheel rolling without slipping (centre speed $v$) moves at:", ["$2v$", "$v$", "0", "$\\sqrt2\\,v$"], 0, "It's $2r$ from the IC at the contact point: $\\omega(2r)=2v$.", L(9, "IC Method"))
mcq("rk-10", T, "Relative acceleration in plane motion: $\\vec a_B=\\vec a_A+$", ["$\\alpha\\vec k\\times\\vec r_{B/A}-\\omega^2\\vec r_{B/A}$", "$\\omega\\vec k\\times\\vec r_{B/A}$", "$2\\vec\\Omega\\times\\vec v_{rel}$", "$\\omega^2\\vec r_{B/A}$"], 0, "Row " + SH + "\nTangential part: $\\alpha r$, perpendicular to $\\vec r_{B/A}$.\nNormal part: $-\\omega^2\\vec r_{B/A}$. The minus sign means it points from B back toward A.", L(9, "Acceleration"))
mcq("rk-11", T, "When a point moves relative to a rotating frame, the Coriolis term is:", ["$2\\vec\\Omega\\times(\\vec v_{B/A})_{xyz}$", "$\\vec\\Omega\\times\\vec r$", "$\\Omega^2r$", "$\\dot{\\vec\\Omega}\\times\\vec r$"], 0, "Rotating-frame row " + SH + ":\n$\\vec a_B=\\vec a_A+\\dot{\\vec\\Omega}\\times\\vec r_{B/A}+\\vec\\Omega\\times(\\vec\\Omega\\times\\vec r_{B/A})+2\\vec\\Omega\\times(\\vec v_{B/A})_{xyz}+(\\vec a_{B/A})_{xyz}$", L(10, "Rotating Frames & Coriolis"))
tf("rk-12", T, "The Coriolis acceleration is zero if the collar doesn't move along the rotating rod, or if the rod isn't rotating.", True, "It needs both $\\Omega\\ne0$ and $(\\vec v_{B/A})_{xyz}\\ne0$, and they can't be parallel.", L(11, "Coriolis Acceleration"))
sa("rk-13", T, "When should you use the absolute-motion (analytical) method for a mechanism?", "When the geometry gives a position relation such as $x=f(\\theta)$. Differentiate with respect to time (chain rule) to get $v$, then again for $a$.", "Show the chain rule step, e.g. $\\dot x=f'(\\theta)\\,\\dot\\theta$.\nThis is an alternative to the relative-motion rows " + SH + ".", L(10, "Absolute Motion"), ["position vs angle", "differentiate in time", "chain rule"])

T = "Kinetics: Newton's 2nd law (Ch 12, 16)"
mcq("nk-01", T, "Newton's second law in n–t coordinates, normal direction:", ["$\\sum F_n=m\\,v^2/\\rho$", "$\\sum F_n=m\\dot v$", "$\\sum F_n=0$", "$\\sum F_n=mv$"], 0, "(derived) $\\sum\\vec F=m\\vec a$ " + SH + " with $\\vec a=a_t\\vec e_t+\\frac{v^2}\\rho\\vec e_n$ " + SH + ".\nTangential direction: $\\sum F_t=m\\dot v$.", L("11b & 13", "Newton's Second Law"))
tf("nk-02", T, "Centrifugal force is a real force that belongs on a free-body diagram in an inertial frame.", False, "Only real forces go on the FBD. $mv^2/\\rho$ belongs on the kinetic diagram (the $m\\vec a$ side).", L("11b & 13", "Newton's Second Law"))
mcq("nk-03", T, "For a rigid body in plane motion, the equations of motion are:", ["$\\sum\\vec F=m\\vec a_G$ and $\\sum M_G=\\bar I\\alpha$", "$\\sum\\vec F=0$ and $\\sum M=0$", "$\\sum\\vec F=m\\vec a$ at any point and $\\sum M_O=0$", "$\\sum M_G=ma_G$"], 0, "$\\sum\\vec F=m\\vec a$ and $\\sum\\vec M=I\\vec\\alpha$ " + SH + "\nSum moments about G, or about a fixed axis O using $I_O$.\nAbout any other point P, add the moment of $m\\vec a_G$.", L(14, "Rigid Bodies – Forces & Acceleration"))
tf("nk-04", T, "In pure translation $\\alpha=0$, so $\\sum M_G=0$, but moments about other points need not be zero.", True, "About a point P: $\\sum M_P$ = moment of $m\\vec a_G$ about P.", L(14, "Translation"))
mcq("nk-05", T, "For rotation about a fixed axis O (not through G), a convenient moment equation is:", ["$\\sum M_O=I_O\\alpha$, with $I_O=\\bar I+mr^2$", "$\\sum M_O=\\bar I\\alpha$", "$\\sum M_O=0$", "$\\sum M_O=ma_Gd$ only"], 0, "$\\sum M=I\\alpha$ and $I_0=\\bar I+mr^2$ " + SH + "\nSumming about O removes the unknown pin reactions from the equation.", L(15, "Fixed-Axis Rotation Kinetics"))
mcq("nk-06", T, "The parallel-axis theorem is:", ["$I_0=\\bar I+mr^2$", "$I_0=\\bar I-mr^2$", "$I_0=mr^2$", "$I_0=\\bar I\\,r^2$"], 0, "Row " + SH + "\n$\\bar I$ is about the parallel axis through G; $r$ is the distance between the two axes.", L(15, "Fixed-Axis Rotation Kinetics"))
sa("nk-07", T, "For a wheel rolling with friction, how do you decide between 'rolls without slipping' and 'slips'?", "Assume no slip ($a_G=r\\alpha$) and solve for the friction force $F$. Check $F\\le\\mu_sN$. If the check fails, it slips: use $F=\\mu_kN$ and treat $a_G$ and $\\alpha$ as independent.", "This is an assume-and-check procedure. State the assumption, then the check.\n" + CRIB, L(16, "Rolling with Friction"), ["assume no slip", "a = rα", "check F ≤ μs N", "else F = μk N"])
mcq("nk-08", T, "A disk pulled horizontally at its centre rolls without slipping. Static friction at the contact:", ["Acts opposite to the pull and supplies the moment that spins the disk up", "Is zero", "Acts with the pull", "Equals $\\mu_kN$"], 0, "$\\sum M_G=\\bar I\\alpha$ " + SH + ": only friction has a moment about G.\nWithout friction the disk would slide without rotating.", L(16, "Rolling with Friction"))
tf("nk-09", T, "A thin ring ($mr^2$) has a larger moment of inertia about its axis than a solid disk ($\\tfrac12mr^2$) of the same mass and radius.", True, "The ring's mass sits farther from the axis, so it rolls down an incline more slowly.\nShape moments of inertia " + DEF + ".", L(15, "Rotation Kinetics"))

T = "Work & energy (Ch 13, 17)"
mcq("we-01", T, "The principle of work and energy is:", ["$U^{tot}_{1\\to2}=\\Delta T$", "$T_1=T_2$ always", "$\\sum F=ma$", "$mv_1+\\int Fdt=mv_2$"], 0, "$U^{tot}_{1\\to2}=\\Delta T$, $T=\\tfrac12mv^2$ " + SH + "\nWork is a scalar, so there are no components to resolve.", L(17, "Energy Method (Particles)"))
mcq("we-02", T, "The work done by a linear spring as it stretches from $x_1$ to $x_2$ is:", ["$-\\tfrac12k(x_2^2-x_1^2)$", "$\\tfrac12k(x_2-x_1)^2$", "$-k(x_2-x_1)$", "$kx_2x_1$"], 0, "(derived) $U=\\int\\vec F\\cdot d\\vec r$ " + SH + " with $F=-kx$\n$=-\\tfrac12k(x_2^2-x_1^2)$\n$x$ is measured from the unstretched length; it appears as $\\tfrac12kx^2$ in the energy row " + SH + ".\nIt's negative when stretching further, because the spring pulls back.", L(17, "Energy Method (Particles)"))
tf("we-03", T, "The normal force on a particle sliding along a fixed surface does no work.", True, "It's perpendicular to the displacement, so $\\vec F\\cdot d\\vec r=0$ " + SH + ".\nKinetic friction does negative work.", L(17, "Energy Method (Particles)"))
mcq("we-04", T, "In the sheet's energy equation $\\tfrac12mv_1^2+mgy_1+\\tfrac12kx_1^2+U^{nc}_{1\\to2}=\\tfrac12mv_2^2+mgy_2+\\tfrac12kx_2^2$, what is $U^{nc}_{1\\to2}$?", ["The work of non-conservative forces (friction, applied forces)", "Gravity's work", "Spring work", "Always zero"], 0, "Energy row " + SH + "\nWhen only gravity and springs do work, $U^{nc}=0$ and energy is conserved.\nFriction makes $U^{nc}<0$.", L(17, "Energy Method (Particles)"))
mcq("we-05", T, "The kinetic energy of a rigid body in plane motion is:", ["$\\tfrac12mv^2+\\tfrac12I\\omega^2$ (with $v=v_G$ and $I=\\bar I$)", "$\\tfrac12mv^2$ only", "$\\tfrac12I\\omega$", "$mv+I\\omega$"], 0, "Rigid-body $T$ row " + SH + "\nFor fixed-axis rotation about O: $T=\\tfrac12I_O\\omega^2$ (derived with $I_0=\\bar I+mr^2$ " + SH + ").", L(18, "Energy Method (Rigid Bodies)"))
tf("we-06", T, "For a wheel rolling without slipping, the friction force at the contact does no work.", True, "The contact point has zero velocity, so $P=\\vec F\\cdot\\vec v=0$ " + SH + ".", L(18, "Energy Method (Rigid Bodies)"))
mcq("we-07", T, "Power is:", ["$P=\\dfrac{dU}{dt}=\\vec F\\cdot\\vec v$", "$P=Fd$", "$P=\\tfrac12mv^2$", "$P=F/v$"], 0, "Power row " + SH + "\nFor a couple: $P=M\\omega$. Efficiency = output power ÷ input power.", L(17, "Energy Method"))
tf("we-08", T, "The work of a couple is $U_{1\\to2}=\\int\\vec M\\cdot d\\vec\\theta$, which is $M\\Delta\\theta$ for constant $M$.", True, "Couple row " + SH + "\nPositive when $M$ and the rotation are in the same direction.", L(18, "Energy Method (Rigid Bodies)"))
mcq("we-09", T, "In the sheet's energy equation, the gravity term $mgy$ uses:", ["$y$ measured upward from any chosen datum", "$y$ measured downward", "the absolute height above sea level", "$y^2$"], 0, "Energy row " + SH + "\nThe datum doesn't matter, because only $mg(y_2-y_1)$ affects the result.", L(17, "Energy Method"))

T = "Impulse & momentum (Ch 13, 17)"
mcq("im-01", T, "The principle of linear impulse and momentum is:", ["$m\\vec v_1+\\int\\vec F\\,dt=m\\vec v_2$", "$U=\\Delta T$", "$\\vec F=m\\vec a$", "$mv_1^2+Ft=mv_2^2$"], 0, "Row " + SH + "\nIt's a vector equation, so write it in components. Best when forces act over a known time.", L(19, "Impulse & Momentum (Particles)"))
mcq("im-02", T, "Linear momentum of a system is conserved when:", ["The net external impulse is zero", "Energy is conserved", "The bodies stick", "No friction acts between the bodies"], 0, "(derived) Set $\\int\\vec F\\,dt=0$ in the impulse row " + SH + ".\nInternal forces cancel in pairs. Momentum can be conserved in one direction even when it isn't in another.", L(19, "Impulse & Momentum"))
mcq("im-03", T, "The coefficient of restitution is:", ["$e=\\dfrac{v_2'-v_1'}{v_1-v_2}$ (separation ÷ approach)", "$e=\\dfrac{v_1-v_2}{v_2'-v_1'}$", "$e=v_1'/v_1$", "$e=T_2/T_1$"], 0, "Row " + SH + "\n$e=1$: perfectly elastic. $e=0$: perfectly plastic (the bodies stick) " + DEF + ".\nUse it along the line of impact only.", L(22, "Conservation & Restitution"))
tf("im-04", T, "In a perfectly elastic impact ($e=1$), kinetic energy is conserved.", True, "For $e<1$, some kinetic energy is lost to deformation, heat and sound.", L(22, "Restitution"))
tf("im-05", T, "In an oblique impact of smooth spheres, each sphere's momentum along the tangent of the contact plane is conserved separately.", True, "No tangential impulse acts on a smooth contact.\nAlong the line of impact: total momentum plus the $e$ equation " + SH + ".\n" + CRIB, L(22, "Restitution"))
mcq("im-06", T, "The angular momentum of a rigid body about its mass centre (plane motion) is:", ["$H_G=\\bar I\\omega$", "$H_G=m\\bar v$", "$H_G=\\tfrac12\\bar I\\omega^2$", "$H_G=\\bar I\\alpha$"], 0, "Angular impulse row $I\\omega_1+\\int M\\,dt=I\\omega_2$ " + SH + "\nParticle: $\\vec H_0=\\vec r\\times m\\vec v$ " + SH + ".", L(21, "Angular Momentum Method"))
mcq("im-07", T, "Angular momentum about a point O is conserved when:", ["The net angular impulse of external forces about O is zero", "Linear momentum is conserved", "There's no friction", "The body translates"], 0, "(derived) Set $\\int M\\,dt=0$ in the angular impulse row " + SH + ".\nExample: a body pinned at O and hit by a projectile. The large pin impulse has no moment about O.", L(22, "Conservation"))
sa("im-08", T, "When should you choose impulse–momentum over work–energy?", "When time is involved (forces over a time interval), for impacts and impulsive forces, or when relating velocities before and after without knowing distances. Work–energy suits relating speed to position or distance.", "Impact problems need momentum, because energy is lost unless $e=1$.", L(19, "Impulse & Momentum"), ["time", "impacts", "energy for distance"])
tf("im-09", T, "During a short impact, non-impulsive forces like weight and spring forces can usually be neglected.", True, "Their impulse $F\\Delta t\\to0$ as $\\Delta t\\to0$, unlike the large impact force.", L(19, "Impulse & Momentum"))
mcq("im-10", T, "A figure skater pulls her arms in while spinning. Her angular velocity:", ["Increases, because $I\\omega$ is conserved while $I$ drops", "Decreases", "Stays the same", "Drops to zero"], 0, "$I\\omega_1=I\\omega_2$ with no external moment (angular impulse row " + SH + ").\nHer kinetic energy actually increases, from the work her muscles do.", L(22, "Conservation"))

T = "Free vibration (sheet)"
mcq("fv-01", T, "For the free vibration $\\ddot x+\\omega_n^2x=0$ of a mass–spring system, $\\omega_n=$", ["$\\sqrt{k/m}$", "$k/m$", "$\\sqrt{m/k}$", "$2\\pi\\sqrt{k/m}$"], 0, "Vibration rows " + SH + ":\n$\\omega_n=\\sqrt{k/m}$ (rad/s)\n$\\tau=2\\pi/\\omega_n$ (s)\n$f=1/\\tau=\\frac{1}{2\\pi}\\sqrt{k/m}$ (Hz)", "Formulae sheet")
tf("fv-02", T, "Doubling the mass on a spring doubles the period of free vibration.", False, "$\\tau=2\\pi/\\omega_n=2\\pi\\sqrt{m/k}$ " + SH + "\nDoubling $m$ multiplies $\\tau$ by $\\sqrt2\\approx1.41$, not 2.", "Formulae sheet")
